  await db.houseMembership.create({ data: { houseId: house2.id, userId: users[0].id, role: "RESIDENT", status: "ACTIVE" } });
  await db.houseMembership.create({ data: { houseId: house.id, userId: users[4].id, role: "EXECUTOR", status: "ACTIVE" } });
  await db.houseMembership.create({ data: { houseId: house2.id, userId: users[6].id, role: "COUNCIL_MEMBER", status: "ACTIVE" } });
