    expect((await call(1, "PUT", `/api/inspection-assignments/${first.id}/answers/${item1}`, { result: "FAIL", comment: "x".repeat(512) })).statusCode).toBe(200);
    expect((await call(1, "PUT", `/api/inspection-assignments/${first.id}/answers/${item2}`, { result: "FAIL", comment: "", mediaIds: [] })).statusCode).toBe(400);
    expect((await call(1, "PUT", `/api/inspection-assignments/${first.id}/answers/${item1}`, { result: "FAIL", comment: "Дефект", mediaIds: [] })).statusCode).toBe(200);
    expect((await call(1, "PUT", `/api/inspection-assignments/${first.id}/answers/${item2}`, { result: "UNABLE_TO_CHECK", comment: "", mediaIds: [] })).statusCode).toBe(400);
    expect((await call(1, "POST", `/api/inspection-assignments/${first.id}/complete`, {})).statusCode).toBe(400);
