    expect((await call(2, "PUT", `/api/inspection-assignments/${cleanAssignmentId}/answers/${cleanInspection.items[1].id}`, { result: "PASS" })).statusCode).toBe(200);
    expect((await call(2, "POST", `/api/inspection-assignments/${cleanAssignmentId}/complete`, {})).statusCode).toBe(400);
    expect((await call(2, "PUT", `/api/inspection-assignments/${cleanAssignmentId}/answers/${cleanInspection.items[0].id}`, { result: "PASS" })).statusCode).toBe(200);
    expect((await call(2, "POST", `/api/inspection-assignments/${cleanInspection.assignments[0].id}/complete`, {})).statusCode).toBe(200);
    expect((await db.work.findUniqueOrThrow({ where: { id: cleanWork.id } })).status).toBe("WAITING");
    const recoveryWork = await db.work.create({ data: { houseId: house.id, executorUserId: users[3].id, title: `Recovery work ${key}`, description: "Проверка восстановления", category: "COMMON_AREAS", submittedForInspectionAt: new Date() } });
