    expect(recoveryCreated.statusCode).toBe(201);
    const recoveryInspection = await db.inspection.findUniqueOrThrow({ where: { id: recoveryCreated.json().id }, include: { assignments: true, items: true } });
    for (const item of recoveryInspection.items) expect((await call(2, "PUT", `/api/inspection-assignments/${recoveryInspection.assignments[0].id}/answers/${item.id}`, { result: "PASS" })).statusCode).toBe(200);
    await db.inspectionAssignment.update({ where: { id: recoveryInspection.assignments[0].id }, data: { status: "COMPLETED", completedAt: new Date() } });
